INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7683547, 1257845, 30861, '<td valign="top">Well, since you ASK :-) The rocker press is the one I use nearly all the time, it does a good job without pureeing the snot out of the bulb. Sprinkle a little salt on the puree and keep working it, yum :-) As for the press, *that* sort of press is anathema to me because it is a wedge-squeeze setup and it applies WAY too uneven a pressure across the bulb. When I *do* want to puree my garlic I use a "pneumatic" press, the kind with a round barrel and the plunger on a hinged lever arm, that presses down evenly on the entire clove at once. Thanks for asking :-)<br/> <br/>If you wanna know why I''m waxing so eloquent, go to my profile and look at my very first DPC Challenge entry, December 2004 :-)<br/> <br/>I like the shot, BTW. I like straightforward visual essays on mundane implements and tools...</td>', 'Well, since you ASK :-) The rocker press is the one I use nearly all the time, it does a good job without pureeing the snot out of the bulb. Sprinkle a little salt on the puree and keep working it, yum :-) As for the press, *that* sort of press is anathema to me because it is a wedge-squeeze setup and it applies WAY too uneven a pressure across the bulb. When I *do* want to puree my garlic I use a "pneumatic" press, the kind with a round barrel and the plunger on a hinged lever arm, that presses down evenly on the entire clove at once. Thanks for asking :-) If you wanna know why I''m waxing so eloquent, go to my profile and look at my very first DPC Challenge entry, December 2004 :-) I like the shot, BTW. I like straightforward visual essays on mundane implements and tools...', '2021-01-06 01:25:54.000000', NULL, 1),
(7683548, 1257871, 30861, '<td valign="top">Terrific control of your image :-) Well done!</td>', 'Terrific control of your image :-) Well done!', '2021-01-06 01:26:55.000000', NULL, 1),
